  const short = { s1: 'See it', s2: 'Full-load current', s3: 'Max efficiency', s4: 'Autotransformer kVA', s5: 'Learn the formulas', s6: 'Also used', s7: 'Key words', s8: 'Why?', s9: 'Compare', s10: 'Solved sums', s11: 'Ratio sums', s12: 'Practice MCQs', s13: 'Takeaway', test: 'Missing-letter test', prog: 'My progress & mock', pyq: 'MCQs', bank: 'Question bank', gate: 'GATE sums', every: 'Every formula', try: 'Simulator', book: 'Everywhere in the book', tamil: 'Tamil stories' };
