  let cur = '';
  const io = new IntersectionObserver(es => {
    es.forEach(e => {
      if (!e.isIntersecting || e.target.id === cur) return;
      cur = e.target.id;
      document.querySelectorAll('[data-sec]').forEach(a => a.classList.toggle('on', a.dataset.sec === cur));
      const c = chips.querySelector(`[data-sec="${cur}"]`);
      if (c && getComputedStyle(chips).display !== 'none') chips.scrollLeft = c.offsetLeft - chips.clientWidth / 2 + c.offsetWidth / 2;
    });
  }, { rootMargin: '-30% 0px -65% 0px' });
  SECS.forEach(([id]) => io.observe(document.getElementById(id)));

  /* ---------- the four tabs: Learn · Simulate · Practice · Book pages ---------- */
  let pane = '';
  function showPane(p, scroll) {
    if (!PANES[p]) p = 'learn';
    if (p !== pane) {
      pane = p;
      document.querySelectorAll('.pane').forEach(el => { el.hidden = el.dataset.pane !== p; });
      document.querySelectorAll('.pbar [data-pane]').forEach(b => b.setAttribute('aria-selected', String(b.dataset.pane === p)));
      document.querySelectorAll('[data-sec]').forEach(a => { a.hidden = paneOf(a.dataset.sec) !== p; });
      try { localStorage.setItem('tf-pane', p); } catch (e) {}
      if (p === 'sim') calc();
      document.dispatchEvent(new CustomEvent('tf:pane', { detail: p }));
    }
    if (scroll) { const top = $('.pbar').getBoundingClientRect().top + scrollY - 70; if (scrollY > top) scrollTo(0, top); }
  }
  $('.pbar').addEventListener('click', e => { const b = e.target.closest('[data-pane]'); if (b) showPane(b.dataset.pane, true); });
