    const tg = e.target.closest('.tg');
    if (tg) { const box = tg.closest('.ss').querySelector('.' + tg.dataset.t); box.hidden = !box.hidden; tg.classList.toggle('on', !box.hidden);
      tg.textContent = { st: box.hidden ? (tg.textContent.includes('rule') ? 'Show rule' : 'Show steps') : (tg.textContent.includes('rule') ? 'Hide rule' : 'Hide steps'), an: box.hidden ? 'Show answer' : 'Hide answer' }[tg.dataset.t]; return; }
