    if (!box.firstChild) box.innerHTML = img('gate/q' + g[0] + '.webp', g[8], 'Question') + `<div class="ans">Answer: ${esc(g[4])}</div>` + img('gate/s' + g[0] + '.webp', g[9], 'Worked solution');
